import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static int n;
     static long[]  a, pref;
     
     static long sum(int k){
         return pref[k];
     }
     static long calc(int b, int c){
         int x = n-b-c;
         int y = n+b-c;
         int z = n+b+2*c;
         return 2L*sum(x) + sum(y) + 3L*sum(z);
     }
     
     static long bestForC(int c){
         int l=0, r = n-c;
         while(l<r){
             int mid = l+(r-l)/2;
             if(calc(mid, c) <= calc(mid+1, c)){
                 l = mid+1;
             }else{
                 r = mid;
             }
         }
         return calc(l,c);
     }
	public static void main (String[] args) throws IOException
	{
	    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
	    int t = Integer.parseInt(br.readLine().trim());
	    StringBuilder out = new StringBuilder();
	    
	    while(t-- > 0){
	        n = Integer.parseInt(br.readLine().trim());
	        
	        a = new long[3*n];
	        pref = new long[3*n+1];
	        
	        StringTokenizer st = new StringTokenizer("");
	        int idx = 0;
	        while(idx< 3*n){
	            if(!st.hasMoreTokens()){
	                st = new StringTokenizer(br.readLine());
	            }
	            while(st.hasMoreTokens() && idx<3*n){
	                a[idx++] = Long.parseLong(st.nextToken());
	            }
	        }
	        Arrays.sort(a);
	        for(int i=0; i<3*n; i++){
	            pref[i+1] = pref[i] + a[3*n-1-i];
	        }
	        int l=0, r=n;
	        while(l<r){
	            int mid = l+(r-l)/2;
	            if(bestForC(mid) <= bestForC(mid+1)){
	                l = mid+1;
	            }else{
	                r = mid;
	            }
	        }
	        out.append(bestForC(l)).append('\n');
	    }
	    System.out.print(out);
		// your code goes here

	}
}
